-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Oficinas de Impressão 3D e Robótica' and a.numero = 5
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 5 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 05', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 05 (10 questões discursivas)',
      '/MATERIAIS/RIO_DO_SUL_MAIS_TECH/OFICINAS_IMPRESSAO_3D_ROBOTICA/ATIVIDADES/ATIVIDADE-PRATICA-AULA-05.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que eram os autômatos da Antiguidade e da Idade Média e dê um exemplo.', 0.3, 'Autômatos eram máquinas que imitavam movimentos, como relógios e figuras mecânicas.', 'Nota cheia: explica que imitavam movimentos e dá um exemplo (relógio ou figura mecânica). Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 1, 2, 'Em 1920 surgiu a palavra "robô". Diga em que obra ela apareceu, quem a escreveu e de que ideia ela vem.', 0.3, 'Apareceu na peça teatral R.U.R., do tcheco Karel Čapek; a palavra vem de "trabalho forçado".', 'Nota cheia: peça (R.U.R.), autor (Karel Čapek) e origem (trabalho forçado). Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 1, 3, 'Diga qual foi o primeiro robô industrial, em que ano entrou em uso e onde foi instalado.', 0.4, 'O Unimate, em 1961, instalado em uma linha de montagem automotiva.', 'Nota cheia: nome (Unimate), ano (1961) e local (linha de montagem automotiva). Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 2, 1, 'Explique o que aconteceu nas fábricas nas décadas de 1970 e 1980 com os robôs.', 0.3, 'Os robôs com braços programáveis se espalharam pelas fábricas.', 'Nota cheia: cita os braços programáveis e a presença nas fábricas. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 2, 2, 'Cite dois exemplos de robôs de serviço que se espalharam a partir dos anos 2000.', 0.3, 'Aspiradores (robôs aspiradores) e drones.', 'Nota cheia: dois exemplos corretos de robôs de serviço (aspirador, drone, robô de limpeza ou assistente). Metade: um. Zero: nenhum correto.'),
      (v_atividade, 2, 3, 'Explique o que são os robôs colaborativos (cobots) e como eles trabalham em relação às pessoas.', 0.4, 'Cobots são robôs colaborativos que trabalham ao lado das pessoas.', 'Nota cheia: diz que são robôs colaborativos e que trabalham ao lado das pessoas. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 3, 1, 'Escreva a definição de robô, indicando o que ele percebe, o que decide e como age, e o componente de cada função.', 0.4, 'Robô é uma máquina que percebe o ambiente (sensores), decide (controlador) e age (atuadores), seguindo um programa.', 'Nota cheia: as três funções com os componentes certos (sensores, controlador, atuadores). Metade: as três funções sem os componentes, ou dois pares certos. Zero: um ou nenhum.'),
      (v_atividade, 3, 2, 'Aplique a definição ao aspirador robô: diga o que ele percebe, o que decide e o que faz.', 0.3, 'Exemplo: percebe obstáculos e o ambiente com sensores, decide por onde seguir ou desviar e age movendo-se e aspirando a sujeira.', 'Nota cheia: percepção, decisão e ação do aspirador, coerentes entre si. Metade: dois desses. Zero: um ou nenhum.'),
      (v_atividade, 3, 3, 'Explique qual combinação diferencia um robô de uma máquina comum.', 0.3, 'A combinação de percepção, decisão e ação: o robô percebe, decide e age; a máquina comum não faz essa combinação.', 'Nota cheia: cita a combinação percepção, decisão e ação. Metade: cita só uma ou duas das funções. Zero: sem relação.'),
      (v_atividade, 4, 1, 'Indique qual das duas máquinas é um robô e justifique usando percepção, decisão e ação.', 0.4, 'A máquina B é o robô: o sensor percebe a posição da peça, o controlador decide o ponto de solda e o braço age soldando. A prensa A apenas repete o movimento.', 'Nota cheia: escolhe a B e justifica com percepção, decisão e ação. Metade: escolhe a B com justificativa parcial. Zero: escolhe a A ou não justifica.'),
      (v_atividade, 4, 2, 'Explique o que falta à máquina A para ser considerada um robô.', 0.3, 'Falta perceber o ambiente (sensor) e decidir (controlador) com base no que percebe; ela só age, sempre do mesmo jeito.', 'Nota cheia: aponta a falta de percepção e de decisão. Metade: aponta só uma. Zero: sem relação.'),
      (v_atividade, 4, 3, 'Na máquina B, indique qual parte faz o papel de sensor, de controlador e de atuador.', 0.3, 'Sensor: o sensor que detecta a posição da peça. Controlador: o que decide o ponto de solda. Atuador: o braço que realiza a solda.', 'Nota cheia: as três partes certas. Metade: duas. Zero: uma ou nenhuma.'),
      (v_atividade, 5, 1, 'Classifique o robô em industrial, de serviço ou móvel e justifique com duas características.', 0.4, 'Industrial, porque é fixo (braço articulado) e tem alta precisão e repetição, trabalhando na linha de produção.', 'Nota cheia: classifica como industrial e cita duas características (fixo, braço articulado, alta precisão, repetição). Metade: industrial com uma característica. Zero: outra classificação.'),
      (v_atividade, 5, 2, 'Cite duas tarefas típicas dos robôs industriais, além da pintura.', 0.3, 'Solda e montagem.', 'Nota cheia: as duas tarefas (solda e montagem). Metade: uma. Zero: nenhuma correta.'),
      (v_atividade, 5, 3, 'Aplique os três critérios de classificação (ambiente, mobilidade e tarefa) a esse braço.', 0.3, 'Ambiente: a fábrica (linha de produção). Mobilidade: fixo, não se desloca. Tarefa: pintura repetitiva e precisa.', 'Nota cheia: os três critérios aplicados corretamente. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 6, 1, 'Classifique o robô e justifique pela tarefa e pelo lugar onde ele trabalha.', 0.4, 'É um robô de serviço, porque auxilia pessoas (responde dúvidas) fora da linha de produção, em um ambiente de atendimento.', 'Nota cheia: classifica como de serviço e justifica pela tarefa de auxiliar pessoas e pelo lugar fora da produção. Metade: classifica certo com justificativa parcial. Zero: outra classificação.'),
      (v_atividade, 6, 2, 'Cite dois outros exemplos de robôs de serviço.', 0.3, 'Aspirador e robô de limpeza (também vale assistente ou drone de serviço).', 'Nota cheia: dois exemplos corretos, diferentes do robô do enunciado. Metade: um. Zero: nenhum correto.'),
      (v_atividade, 6, 3, 'Explique a diferença entre um robô de serviço e um robô industrial.', 0.3, 'O industrial é fixo, de alta precisão e repetição, na linha de produção; o de serviço auxilia pessoas fora da linha de produção.', 'Nota cheia: contrasta a tarefa e o lugar (linha de produção × auxiliar pessoas fora dela). Metade: descreve só um dos tipos. Zero: sem relação.'),
      (v_atividade, 7, 1, 'Cite pelo menos três formas de deslocamento que um robô móvel pode usar.', 0.3, 'Rodas, esteiras, pernas e ar.', 'Nota cheia: três ou mais formas certas. Metade: duas. Zero: uma ou nenhuma.'),
      (v_atividade, 7, 2, 'Classifique o drone e justifique pela forma como ele se desloca.', 0.3, 'O drone é um robô móvel, porque se desloca pelo ambiente no ar.', 'Nota cheia: classifica como móvel e cita o deslocamento pelo ar. Metade: só a classificação. Zero: outra classificação.'),
      (v_atividade, 7, 3, 'Explique por que um AGV que leva materiais dentro de uma fábrica pode ser móvel e industrial ao mesmo tempo.', 0.4, 'Porque os critérios podem se sobrepor: o AGV se desloca pelo ambiente (móvel) e trabalha na logística da fábrica (industrial). A escolha se justifica por ambiente, mobilidade e tarefa.', 'Nota cheia: explica a sobreposição com mobilidade (móvel) e ambiente/tarefa de fábrica (industrial). Metade: só um dos lados. Zero: sem relação.'),
      (v_atividade, 8, 1, 'Classifique os três robôs da fábrica e indique o ambiente e a tarefa de cada um.', 0.4, '(1) braço de solda: industrial, fábrica, soldar estruturas; (2) AGV: móvel e industrial, fábrica, levar materiais entre setores e estoques; (3) braço de montagem: industrial, fábrica, colocar peças em motores.', 'Nota cheia: os três classificados com ambiente e tarefa. Metade: dois certos. Zero: um ou nenhum.'),
      (v_atividade, 8, 2, 'Classifique os três robôs do hospital e indique o ambiente e a tarefa de cada um.', 0.3, '(4) robô de limpeza: de serviço, hospital, limpar o piso; (5) robô assistente: de serviço, hospital, orientar visitantes; (6) robô de refeições: de serviço e móvel, hospital, levar refeições aos quartos.', 'Nota cheia: os três classificados com ambiente e tarefa (o 6 aceito como móvel, de serviço ou ambos). Metade: dois certos. Zero: um ou nenhum.'),
      (v_atividade, 8, 3, 'Aponte dois robôs da lista que se encaixam em mais de um tipo e justifique.', 0.3, 'O AGV é móvel e industrial (se desloca e trabalha na logística da fábrica); o robô de refeições é móvel (rodas) e de serviço (auxilia pessoas). O robô de limpeza também pode ser móvel e de serviço.', 'Nota cheia: dois robôs que se encaixam em mais de um tipo, com justificativa por mobilidade, ambiente ou tarefa. Metade: um com justificativa, ou dois sem. Zero: nenhum.'),
      (v_atividade, 9, 1, 'Indique o tipo de robô e a aplicação (montagem, solda ou logística) para cada um dos três setores.', 0.4, 'Montagem: braços robóticos (industriais); solda: células robotizadas com braço (industriais); logística: veículos autônomos AGV (móveis).', 'Nota cheia: os três setores associados a robô e aplicação certos. Metade: dois. Zero: um ou nenhum.'),
      (v_atividade, 9, 2, 'Explique o que o robô faz na montagem e o que ele faz na logística.', 0.3, 'Na montagem, braços robóticos colocam peças em motores, eletrodomésticos e componentes. Na logística, os AGV levam materiais entre setores e estoques.', 'Nota cheia: as duas funções explicadas. Metade: uma. Zero: nenhuma.'),
      (v_atividade, 9, 3, 'Explique duas vantagens das células robotizadas de solda.', 0.3, 'Soldam estruturas metálicas com precisão e com segurança.', 'Nota cheia: as duas vantagens (precisão e segurança). Metade: uma. Zero: nenhuma.'),
      (v_atividade, 10, 1, 'Explique o que o robô passou a fazer no lugar do soldador.', 0.3, 'O robô passou a fazer o trabalho repetitivo da solda, repetindo o mesmo ponto milhares de vezes.', 'Nota cheia: cita a solda e o caráter repetitivo. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 10, 2, 'Explique qual é o novo papel do soldador depois da automação.', 0.3, 'O soldador passa a programar e supervisionar a célula robotizada em vez de fazer o trabalho repetitivo.', 'Nota cheia: cita programar e supervisionar. Metade: só um dos dois. Zero: sem relação.'),
      (v_atividade, 10, 3, 'Indique as três áreas de profissionais que a automação pede e diga qual delas é a do soldador que programa a célula.', 0.4, 'Programação, manutenção e projeto. O soldador que programa a célula pertence à área de programação.', 'Nota cheia: as três áreas e a área de programação indicada. Metade: as três áreas sem a indicação, ou duas áreas com a indicação. Zero: uma ou nenhuma.');
end $$;
